import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import font_size_sample from '~/shared/assets/img/font_size_sample.png';
import i18n from '~/shared/i18n/i18n';
import { useLargeFontSize } from '~/shared/lib/hooks/use-app-font-size';
import { ToggleSwitch } from '~/shared/ui/toggle-switch/toggle-switch';
import { ToggleSwitchSection } from '~/shared/ui/toggle-switch/toggle-switch-section';

const ToggleFontSize = () => {
  const { isLargeFontSizeEnabled, toggleFontSize } = useLargeFontSize();
  return <ToggleSwitch on={isLargeFontSizeEnabled} onToggle={toggleFontSize} />;
};

export const SettingFontSizePage = () => {
  useSetHeaderTitle(i18n.t('fontSizeSetting'));

  return (
    <>
      <ToggleSwitchSection label={i18n.t('useLargeFont')} desc={i18n.t('text:largeFontForWalletAndTransfer')}>
        <ToggleFontSize />
      </ToggleSwitchSection>

      <div className="font-example">
        <img src={font_size_sample} className="font-size-sample" />
        <div className="font-example-inner">
          <div className="fs-normal">{i18n.t('koreanCharacter')}</div>
          <div className="fs-step">
            <span>point</span>
            <span>point</span>
            <span>point</span>
          </div>
          <div className="fs-large">{i18n.t('koreanCharacter')}</div>
        </div>
      </div>
    </>
  );
};
